-- Table: hrm_claim_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_claim_detail (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    claim_id     BIGINT NOT NULL REFERENCES hrm_claim(id) ON DELETE CASCADE,
    line_number  INTEGER NOT NULL CHECK (line_number > 0),
    expense_date DATE NOT NULL,
    coa_id       BIGINT NOT NULL REFERENCES masterdata_coa(id),
    description  TEXT,
    amount       NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    receipt_url  TEXT,
    UNIQUE (claim_id, line_number)
);
